#include <iostream>
#include <cassert>
#include "vec.hpp"

int main() {
    // Test basic vector creation and access
    qm::Vec a(3, 1.0);
    qm::Vec b(3, 2.0);

    assert(a.size() == 3);
    assert(b.size() == 3);
    assert(a[0] == 1.0);
    assert(b[0] == 2.0);

    // Test vector addition
    auto c = a + b;
    assert(c.size() == 3);
    assert(c[0] == 3.0);

    // Test vector subtraction
    auto d = b - a;
    assert(d.size() == 3);
    assert(d[0] == 1.0);

    // Test scalar multiplication
    auto e = a * 2.0;
    assert(e.size() == 3);
    assert(e[0] == 2.0);

    // Test scalar division
    auto f = b / 2.0;
    assert(f.size() == 3);
    assert(f[0] == 1.0);

    // Test unary minus
    auto g = -a;
    assert(g.size() == 3);
    assert(g[0] == -1.0);

    // Test assignment
    qm::Vec h(3, 0.0);
    h = a + b;
    assert(h.size() == 3);
    assert(h[0] == 3.0);

    // Test compound assignment
    h += a;
    assert(h[0] == 4.0);

    h -= b;
    assert(h[0] == 2.0);

    // Test reductions
    assert(qm::sum(a) == 3.0);
    assert(qm::dot(a, b) == 6.0);
    assert(qm::max(a) == 1.0);

    // Test shift operation
    auto shifted = qm::shift(a, 1);
    assert(shifted.size() == 3);

    // Test complex expression
    auto complex = (a + b) * 2.0 - a;
    assert(complex.size() == 3);
    assert(complex[0] == 3.0);

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

