#include <iostream>
#include <cassert>
#include "vec.hpp"

int main() {
    // Test basic vector creation and access
    qm::Vec a(3, 1.0);
    qm::Vec b(3, 2.0);

    assert(a.size() == 3);
    assert(b.size() == 3);
    assert(a[0] == 1.0);
    assert(b[0] == 2.0);

    // Test vector addition
    auto c = a + b;
    assert(c.size() == 3);
    assert(c[0] == 3.0);

    // Test vector subtraction
    auto d = b - a;
    assert(d.size() == 3);
    assert(d[0] == 1.0);

    // Test scalar multiplication
    auto e = a * 2.0;
    assert(e.size() == 3);
    assert(e[0] == 2.0);

    // Test scalar division
    auto f = b / 2.0;
    assert(f.size() == 3);
    assert(f[0] == 1.0);

    // Test unary minus
    auto g = -a;
    assert(g.size() == 3);
    assert(g[0] == -1.0);

    // Test assignment
    qm::Vec h(3, 0.0);
    h = a + b;
    assert(h.size() == 3);
    assert(h[0] == 3.0);

    // Test compound assignment
    h += a;
    assert(h[0] == 4.0);

    h -= b;
    assert(h[0] == 2.0);

    // Test reductions
    assert(qm::sum(a) == 3.0);
    assert(qm::dot(a, b) == 6.0);
    assert(qm::max(a) == 1.0);

    // Test shift operation
    auto shifted = qm::shift(a, 1);
    assert(shifted.size() == 3);

    // Test complex expression
    auto complex = (a + b) * 2.0 - a;
    assert(complex.size() == 3);
    // (1 + 2) * 2 - 1 = 3 * 2 - 1 = 6 - 1 = 5
    assert(complex[0] == 5.0);

    // Test aliasing behavior: a = a + b
    qm::Vec alias_test(3, 1.0);
    qm::Vec alias_test2(3, 2.0);
    alias_test = alias_test + alias_test2;
    assert(alias_test[0] == 3.0);

    // Test aliasing behavior: a = b - a
    alias_test = qm::Vec(3, 5.0);
    alias_test2 = qm::Vec(3, 2.0);
    alias_test = alias_test2 - alias_test;
    assert(alias_test[0] == -3.0);

    // Test aliasing behavior: shift operation
    qm::Vec shift_test(4, 1.0);
    shift_test[1] = 2.0;
    shift_test[2] = 3.0;
    shift_test[3] = 4.0;
    auto shifted_result = qm::shift(shift_test, 1);
    assert(shifted_result[0] == 4.0);  // Should be the last element
    assert(shifted_result[1] == 1.0);  // Should be the first element
    assert(shifted_result[2] == 2.0);  // Should be the second element
    assert(shifted_result[3] == 3.0);  // Should be the third element

    // Test that expressions stay valid after full expression ends
    auto temp_expr = (a + b) * 2.0;
    assert(temp_expr[0] == 6.0);  // (1 + 2) * 2 = 6

    // Test with temporary Vec
    auto temp_expr2 = qm::Vec(3, 1.0) + b;
    assert(temp_expr2[0] == 3.0);  // 1 + 2 = 3

    // Test with function returning expression
    auto f = [](const qm::Vec& v) -> auto {
        return v + v;
    };
    auto temp_expr3 = f(a);
    assert(temp_expr3[0] == 2.0);  // 1 + 1 = 2

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

